type QuoteItem = { code: string; quantity?: string; colors?: string; sizes?: string; notes?: string };
type Attachment = { id: string; name: string; contentType: string; size: number; uploadedAt: string; revokedAt?: string; revokedBy?: string; revocationReason?: string };
type QuotationLine = { code: string; description: string; quantity: string; unitPrice: string };
type RevisionBrief = { reasons: string[]; affectedCodes: string[]; targetQuantity: string; targetUnitPrice: string; targetTradeTerm: string; requestedDelivery: string; requestedPayment: string; requestedPacking: string; requestedSample: string };
type Quotation = { quoteNumber: string; version: string; currency: string; tradeTerm: string; validUntil: string; leadTime: string; paymentTerms: string; packing: string; sampleTerms: string; notes: string; createdAt: string; lines: QuotationLine[]; status?: string; issuedAt?: string; buyerDecision?: string; buyerNote?: string; buyerRespondedAt?: string; revisionBrief?: RevisionBrief | null; quoteEmailSent?: boolean };
type PaymentMilestone = { id: string; label: string; amount: string; dueDate: string; status: "planned" | "due" | "paid" | "waived"; paidAt: string; reference: string; note: string };
type OrderChecklist = { productSpecification: string; sampleDecision: string; quantitySizeRatio: string; colorsMaterials: string; packingLabeling: string; priceTradeTerm: string; paymentTerms: string; deliveryWindow: string };
type OrderHandoff = { method: "alibaba_trade_assurance" | "contract"; orderReference: string; orderUrl: string; confirmedAt: string; note: string; fulfillmentStatus: string; carrier: string; trackingNumber: string; paymentCurrency?: string; paymentMilestones?: PaymentMilestone[]; orderChecklist?: OrderChecklist; updatedAt?: string };
type BuyerOrderRequest = { id: string; quoteNumber: string; preferredOrderChannel: "alibaba_trade_assurance" | "contract" | "need_guidance"; legalCompanyName: string; purchasingContact: string; purchaseOrderReference: string; destination: string; requestedWindow: string; instructions: string; status: string; submittedAt: string };
type InquiryMessage = { id: string; sender: "buyer" | "sales"; body: string; sentAt: string; notificationSent?: boolean };
type PipelineEvent = { from: string; to: string; changedAt: string; actor: string; reason: string };
type OrderDocument = { id: string; name: string; title: string; category: string; note: string; contentType: string; size: number; uploadedAt: string; notificationSent?: boolean; revokedAt?: string; revokedBy?: string; revocationReason?: string };
type DocumentAudit = { id: string; kind: string; fileId: string; fileName: string; action: string; reason: string; actor: string; changedAt: string };
type SampleReviewRound = { round: number; sampleReference: string; styleCodes: string; purpose: string; reviewScope: string; deliverables: string; acceptanceCriteria: string; exclusions: string; status: string; openedAt: string; decision: string; buyerNote: string; respondedAt: string };
type SampleProgram = { status: string; sampleReference?: string; styleCodes: string; quantity: string; sizes: string; colors: string; purpose: string; reviewScope: string; deliverables?: string; acceptanceCriteria?: string; exclusions?: string; reviewRounds?: SampleReviewRound[]; currency: string; sampleCharge: string; chargeStatus: string; paidAt: string; courier: string; trackingNumber: string; shippedAt: string; expectedDelivery: string; note: string; buyerDecision?: string; buyerNote?: string; buyerRespondedAt?: string; updatedAt?: string; history?: { from: string; to: string; changedAt: string; actor: string }[] };
type RecommendationFollowUp = { id: string; stage: RecommendationFollowUpStage; body: string; sentAt: string; sentBy: string; notificationSent?: boolean };
type ProductRecommendation = { id: string; title: string; introduction: string; items: { code: string; reason: string }[]; nextStep: string; status: string; issuedAt: string; issuedBy: string; buyerDecision?: string; selectedCodes?: string[]; buyerNote?: string; buyerRespondedAt?: string; notificationSent?: boolean; responseNotificationSent?: boolean; followUps?: RecommendationFollowUp[] };
type CommercialAnalytics = {
  period: { days: number; from: string; to: string; consentNote: string };
  funnel: { productViews: number; quoteAdds: number; quoteBuilderViews: number; quoteRequests: number; inquiries: number; qualified: number; sampleDiscussion: number; quoted: number; quoteAccepted: number; orderSetupRequested: number; orders: number };
  supporting: { mobileMenuOpens: number; mobileMenuLinks: number; sourcingProgramViews: number; sourcingProgramCtas: number; lineSheetLeads: number; lineSheetDownloads: number; productSpecSheets: number; buyerMessages: number; buyerFiles: number; buyerDocuments: number; quoteRevisions: number; quoteDeclines: number; overdue: number };
  stageActivity: { stage: string; count: number }[]; lossReasons: { reason: string; count: number }[];
  sources: { label: string; events: number; inquiries: number }[];
  products: { code: string; views: number; compares: number; specSheets: number; quoteAdds: number; inquiries: number }[];
  coverage: { eventsLoaded: number; inquiriesLoaded: number; truncated: boolean };
};
type ReminderSummary = { today: string; windowEnds: string; counts: { followUps: number; recommendations: number; quotes: number; payments: number; total: number }; followUps: { reference: string; company: string; owner: string; dueDate: string; action: string }[]; recommendations: { reference: string; company: string; owner: string; recommendationId: string; styles: string; dueDate: string; stage: RecommendationFollowUpStage; timing: string }[]; quotes: { reference: string; company: string; owner: string; quoteNumber: string; validUntil: string; timing: string }[]; payments: { reference: string; company: string; owner: string; orderReference: string; label: string; amount: string; currency: string; dueDate: string; timing: string }[] };
type Inquiry = {
  reference: string; receivedAt: string; status: string; notificationSent?: boolean; internalTest?: boolean;
  styleCode: string; styleLabel: string; name: string; company: string; buyerType: string; market: string; quantity: string;
  email: string; whatsapp: string; requirements: string; projectPath?: string; sourcingProgram?: string; sampleQuantity?: string; bulkQuantity?: string; preferredTradeTerm?: string; deliveryDestination?: string; deliveryTiming?: string;
  existingSole?: string; changesRequired?: string; targetValues?: string; ndaRequired?: string; items?: QuoteItem[];
  owner?: string; nextAction?: string; nextActionDue?: string; internalNote?: string; buyerUpdate?: string; lastContactedAt?: string; updatedAt?: string; lostReason?: string; pipelineHistory?: PipelineEvent[];
  attachments?: Attachment[]; quotations?: Quotation[]; recommendationSets?: ProductRecommendation[]; sampleProgram?: SampleProgram | null; buyerOrderRequests?: BuyerOrderRequest[]; orderHandoff?: OrderHandoff | null; messages?: InquiryMessage[]; orderDocuments?: OrderDocument[];
  documentAudit?: DocumentAudit[];
  attribution?: { utmSource?: string; utmMedium?: string; utmCampaign?: string }; page?: string;
};

const PIPELINE = [
  ["new", "New"], ["qualified", "Qualified"], ["sample_discussion", "Sample discussion"], ["quoted", "Quoted"],
  ["negotiation", "Negotiation"], ["order_confirmed", "Order confirmed"], ["lost", "Lost"], ["spam", "Spam"],
] as const;
const LOST_REASONS = [["", "Choose reason"], ["price", "Price / commercial terms"], ["moq", "MOQ mismatch"], ["lead_time", "Lead time"], ["product_fit", "Product / specification fit"], ["trust", "Trust / proof gap"], ["no_response", "Buyer stopped responding"], ["project_cancelled", "Buyer project cancelled"], ["competitor", "Buyer chose competitor"], ["compliance", "Compliance / market access"], ["other", "Other documented reason"], ["legacy_unspecified", "Legacy record — unspecified"]] as const;

function csvCell(value: unknown) { return `"${String(value ?? "").replaceAll('"', '""')}"`; }
function escapeHtml(value: unknown) { return String(value ?? "").replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" })[character] || character); }

function CommercialDashboard({ data, days, loading, onDaysChange, onRefresh }: { data: CommercialAnalytics | null; days: number; loading: boolean; onDaysChange: (days: number) => void; onRefresh: () => void }) {
  const stages = data ? [["Product views", data.funnel.productViews], ["Quote-list adds", data.funnel.quoteAdds], ["Quote requests", data.funnel.quoteRequests], ["Saved inquiries", data.funnel.inquiries], ["Qualified now", data.funnel.qualified], ["Sample stage+", data.funnel.sampleDiscussion], ["Quotation issued", data.funnel.quoted], ["Quote accepted", data.funnel.quoteAccepted], ["Order setup requested", data.funnel.orderSetupRequested], ["Orders confirmed", data.funnel.orders]] as const : [];
  const maximum = Math.max(1, ...stages.map(([, value]) => value));
  return <section className="admin-commercial-dashboard"><div className="admin-dashboard-heading"><div><p className="eyebrow">COMMERCIAL FUNNEL</p><h2>From product interest to confirmed order</h2><p>{data ? `${data.period.from} to ${data.period.to}` : "Load the protected pipeline to calculate commercial activity."}</p></div><div><label>Period<select value={days} onChange={(event) => onDaysChange(Number(event.target.value))}><option value={7}>7 days</option><option value={30}>30 days</option><option value={90}>90 days</option></select></label><button className="button button-small" type="button" onClick={onRefresh} disabled={loading}>{loading ? "Loading…" : "Refresh metrics"}</button></div></div>{data ? <><div className="commercial-funnel">{stages.map(([label, value]) => <article key={label}><div><strong>{label}</strong><span>{value}</span></div><i style={{ width: `${Math.max(value ? 3 : 0, (value / maximum) * 100)}%` }} /></article>)}</div><div className="commercial-supporting"><article><small>MOBILE MENU OPENS</small><strong>{data.supporting.mobileMenuOpens}</strong></article><article><small>MOBILE NAV CLICKS</small><strong>{data.supporting.mobileMenuLinks}</strong></article><article><small>SOURCING-PAGE VIEWS</small><strong>{data.supporting.sourcingProgramViews}</strong></article><article><small>SOURCING CTA CLICKS</small><strong>{data.supporting.sourcingProgramCtas}</strong></article><article><small>LINE-SHEET LEADS</small><strong>{data.supporting.lineSheetLeads}</strong></article><article><small>PDF DOWNLOADS</small><strong>{data.supporting.lineSheetDownloads}</strong></article><article><small>PRODUCT SHEETS</small><strong>{data.supporting.productSpecSheets}</strong></article><article><small>THREAD MESSAGES</small><strong>{data.supporting.buyerMessages}</strong></article><article><small>BUYER FILES</small><strong>{data.supporting.buyerFiles}</strong></article><article><small>BUYER DOCUMENTS</small><strong>{data.supporting.buyerDocuments}</strong></article><article><small>QUOTE REVISIONS</small><strong>{data.supporting.quoteRevisions}</strong></article><article><small>QUOTE DECLINES</small><strong>{data.supporting.quoteDeclines}</strong></article><article><small>FOLLOW-UP OVERDUE</small><strong>{data.supporting.overdue}</strong></article><article><small>RECORD COVERAGE</small><strong>{data.coverage.truncated ? "Partial" : "Loaded"}</strong></article></div><div className="commercial-breakdown"><div><h3>Source signals</h3><div className="commercial-table"><div><strong>Source</strong><strong>Events</strong><strong>Saved records</strong></div>{data.sources.length ? data.sources.map((source) => <div key={source.label}><span>{source.label}</span><span>{source.events}</span><span>{source.inquiries}</span></div>) : <p>No source data in this period.</p>}</div></div><div><h3>Product signals</h3><div className="commercial-table commercial-product-table"><div><strong>Style</strong><strong>Views</strong><strong>Compares</strong><strong>Sheets</strong><strong>Quote adds</strong><strong>Inquiries</strong></div>{data.products.length ? data.products.map((product) => <div key={product.code}><span>{product.code}</span><span>{product.views}</span><span>{product.compares}</span><span>{product.specSheets}</span><span>{product.quoteAdds}</span><span>{product.inquiries}</span></div>) : <p>No product data in this period.</p>}</div></div></div><div className="commercial-breakdown"><div><h3>Stage changes in period</h3><div className="commercial-table commercial-two-column"><div><strong>Stage entered</strong><strong>Count</strong></div>{data.stageActivity.length ? data.stageActivity.map((item) => <div key={item.stage}><span>{item.stage.replaceAll("_", " ")}</span><span>{item.count}</span></div>) : <p>No recorded stage changes. Legacy inquiries may not have history.</p>}</div></div><div><h3>Current lost reasons for period cohort</h3><div className="commercial-table commercial-two-column"><div><strong>Primary reason</strong><strong>Count</strong></div>{data.lossReasons.length ? data.lossReasons.map((item) => <div key={item.reason}><span>{item.reason.replaceAll("_", " ")}</span><span>{item.count}</span></div>) : <p>No lost opportunities in this cohort.</p>}</div></div></div><p className="commercial-data-note">{data.period.consentNote} Funnel stages are operating signals, not unique-person attribution. “Qualified now” and later stages use the inquiry&apos;s current verified record; they must not be presented as platform-reported orders.</p></> : null}</section>;
}

function ReminderCenter({ summary, loading, message, onRefresh, onSend }: { summary: ReminderSummary | null; loading: boolean; message: string; onRefresh: () => void; onSend: () => void }) {
  return <section className="admin-reminder-center"><div className="admin-reminder-heading"><div><p className="eyebrow">SALES REMINDER CENTER</p><h2>Protect active opportunities from silent delay</h2><p>{summary ? `${summary.today} · upcoming window through ${summary.windowEnds}` : "Load the protected pipeline to preview actions."}</p></div><div><button type="button" onClick={onRefresh} disabled={loading}>Refresh preview</button><button className="button button-small" type="button" onClick={onSend} disabled={loading || !summary}>{loading ? "Working…" : "Email today's digest"}</button></div></div>{summary ? <><div className="reminder-counts"><article><small>OVERDUE FOLLOW-UP</small><strong>{summary.counts.followUps}</strong></article><article><small>SHORTLIST FOLLOW-UP</small><strong>{summary.counts.recommendations}</strong></article><article><small>QUOTE EXPIRY</small><strong>{summary.counts.quotes}</strong></article><article><small>PAYMENT DUE</small><strong>{summary.counts.payments}</strong></article><article><small>TOTAL ACTIONS</small><strong>{summary.counts.total}</strong></article></div><div className="reminder-lists"><div><h3>Follow-up</h3>{summary.followUps.slice(0, 6).map((item) => <p key={`${item.reference}-${item.dueDate}`}><strong>{item.reference}</strong><span>{item.dueDate} · {item.company} · {item.owner}</span><small>{item.action}</small></p>)}{!summary.followUps.length && <p>No overdue follow-up.</p>}</div><div><h3>Product shortlist</h3>{summary.recommendations.slice(0, 6).map((item) => <p key={`${item.recommendationId}-${item.stage}`}><strong>{item.styles}</strong><span>{item.dueDate} · {item.timing}</span><small>{item.reference} · {item.company} · {item.stage.replaceAll("_", " ")}</small></p>)}{!summary.recommendations.length && <p>No shortlist follow-up due.</p>}</div><div><h3>Quotation</h3>{summary.quotes.slice(0, 6).map((item) => <p key={item.quoteNumber}><strong>{item.quoteNumber}</strong><span>{item.validUntil} · {item.timing}</span><small>{item.company} · {item.owner}</small></p>)}{!summary.quotes.length && <p>No quotation expiry action.</p>}</div><div><h3>Payment</h3>{summary.payments.slice(0, 6).map((item) => <p key={`${item.reference}-${item.label}-${item.dueDate}`}><strong>{item.label} · {item.currency} {item.amount}</strong><span>{item.dueDate} · {item.timing}</span><small>{item.reference} · {item.company} · {item.owner}</small></p>)}{!summary.payments.length && <p>No payment milestone action.</p>}</div></div></> : null}<p className="reminder-message" aria-live="polite">{message}</p><small>This is an internal action digest. It never sends a buyer follow-up automatically, prove payment, extend a quotation or confirm an order. Only one digest can be sent per calendar day.</small></section>;
}

function RelationshipCenter({ groups, onShowRepeat }: { groups: RelationshipGroup<Inquiry>[]; onShowRepeat: () => void }) {
  const linkedRecords = groups.reduce((sum, group) => sum + group.records.length, 0);
  return <section className="admin-relationship-center"><div className="admin-relationship-heading"><div><p className="eyebrow">BUYER RELATIONSHIP MEMORY</p><h2>Recognize repeat interest without merging evidence</h2><p>Exact email, normalized WhatsApp digits and normalized company names are internal signals only. Review them before treating records as one account.</p></div><button className="button button-small" type="button" onClick={onShowRepeat} disabled={!groups.length}>Show repeat records</button></div><div className="relationship-counts"><article><small>REPEAT ACCOUNT SIGNALS</small><strong>{groups.length}</strong></article><article><small>LINKED RECORDS</small><strong>{linkedRecords}</strong></article></div>{groups.length ? <div className="relationship-groups">{groups.slice(0, 8).map((group) => { const latest = group.records[0]; const companies = [...new Set(group.records.map((record) => record.company).filter(Boolean))]; return <article key={group.id}><div><strong>{latest.company || latest.name}</strong><span>{group.records.length} records · {companies.length} company-name variant{companies.length === 1 ? "" : "s"}</span></div><p>{group.matchBasis.join(" + ")}</p><small>Styles: {group.styleCodes.join(" · ") || "No style recorded"}</small><nav aria-label={`Related inquiries for ${latest.company || latest.name}`}>{group.records.map((record) => <a key={record.reference} href={`#${record.reference}`}>{record.reference} · {record.status.replaceAll("_", " ")}</a>)}</nav></article>; })}</div> : <p className="relationship-empty">No repeat-account signal in the loaded business records.</p>}<small className="relationship-boundary">A match is not proof of legal identity, account ownership or duplicate order. Never merge, delete, quote or disclose records on this signal alone.</small></section>;
}

function RelatedInquiryHistory({ current, group }: { current: Inquiry; group?: RelationshipGroup<Inquiry> }) {
  if (!group) return null;
  return <details className="admin-related-history"><summary>Related inquiry history · {group.records.length} records</summary><p>Matched by {group.matchBasis.join(" + ")}. Verify the buyer before using prior specifications, prices or documents.</p><div>{group.records.map((record) => <a key={record.reference} href={`#${record.reference}`} className={record.reference === current.reference ? "current" : ""}><strong>{record.reference}</strong><span>{record.receivedAt?.slice(0, 10) || "—"} · {record.status.replaceAll("_", " ")} · {record.styleCode}</span></a>)}</div></details>;
}

function ProductRecommendationEditor({ record, token, onSaved }: { record: Inquiry; token: string; onSaved: (record: Inquiry) => void }) {
  const requestedCodes = [...new Set([...(record.items || []).map((item) => item.code), ...record.styleCode.split(/[,/]/).map((code) => code.trim())])].filter((code) => products.some((product) => product.code === code)).slice(0, 5);
  const [selectedCodes, setSelectedCodes] = useState<string[]>(requestedCodes);
  const [title, setTitle] = useState(`Recommended product directions for ${record.company || "your sourcing project"}`);
  const [introduction, setIntroduction] = useState(`These options were selected for review against your stated ${record.market || "target market"} and ${record.buyerType || "buyer"} requirements. Please compare the verified product pages before choosing sample or quotation directions.`);
  const [nextStep, setNextStep] = useState("Choose the relevant styles, then confirm expected quantity, colors, size ratio and whether you want samples before a bulk quotation.");
  const [reasons, setReasons] = useState<Record<string, string>>(() => Object.fromEntries(products.map((product) => [product.code, product.shortDescription])));
  const [message, setMessage] = useState(""); const [issuing, setIssuing] = useState(false);
  const currentRecommendation = record.recommendationSets?.at(-1); const followUps = currentRecommendation?.followUps || []; const nextFollowUpStage: RecommendationFollowUpStage | null = followUps.length === 0 ? "selection_check" : followUps.length === 1 ? "sample_or_quote" : null;
  const followUpBase = followUps.length ? followUps.at(-1)?.sentAt : currentRecommendation?.issuedAt; const followUpDueValue = followUpBase ? new Date(followUpBase) : null; if (followUpDueValue) followUpDueValue.setUTCDate(followUpDueValue.getUTCDate() + (followUps.length ? 4 : 2)); const followUpDue = followUpDueValue?.toISOString().slice(0, 10) || ""; const followUpReady = Boolean(followUpDue && followUpDue <= new Date().toISOString().slice(0, 10));
  const [followUpBody, setFollowUpBody] = useState(""); const [followUpStage, setFollowUpStage] = useState<RecommendationFollowUpStage | null>(null); const [sendingFollowUp, setSendingFollowUp] = useState(false);
  function toggle(code: string) { setSelectedCodes((current) => current.includes(code) ? current.filter((item) => item !== code) : current.length < 5 ? [...current, code] : current); }
  function loadFollowUp() { if (!currentRecommendation || !nextFollowUpStage) return; if (!followUpReady) { setMessage(`The next follow-up is scheduled for ${followUpDue}. Review it then to avoid repetitive contact.`); return; } if (followUpBody.trim()) { setMessage("Clear the current follow-up draft before loading another one."); return; } setFollowUpStage(nextFollowUpStage); setFollowUpBody(buildRecommendationFollowUp(record, currentRecommendation, nextFollowUpStage)); setMessage("Buyer-specific draft loaded. Review every detail before sending."); }
  async function sendFollowUp() {
    if (!currentRecommendation || !followUpStage || followUpStage !== nextFollowUpStage || followUpBody.trim().length < 2) { setMessage("Load and review the next allowed follow-up before sending."); return; }
    setSendingFollowUp(true); setMessage("Saving recommendation follow-up…");
    try { const response = await fetch("/api/admin/inquiry-message", { method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ reference: record.reference, receivedAt: record.receivedAt, message: followUpBody, recommendationId: currentRecommendation.id, recommendationFollowUpStage: followUpStage, sentBy: record.owner }) }); const result = await response.json().catch(() => ({})); if (!response.ok || !result.ok) throw new Error(result.message || "Recommendation follow-up could not be saved."); onSaved(result.record); setFollowUpBody(""); setFollowUpStage(null); setMessage(`Follow-up saved in the private thread${result.notificationSent ? " and emailed" : "; buyer email was not sent"}.`); }
    catch (error) { setMessage(error instanceof Error ? error.message : "Recommendation follow-up could not be saved."); }
    finally { setSendingFollowUp(false); }
  }
  async function issue() {
    if (selectedCodes.length < 2 || selectedCodes.length > 5) { setMessage("Choose 2 to 5 products for a focused recommendation."); return; }
    if (selectedCodes.some((code) => (reasons[code] || "").trim().length < 8)) { setMessage("Write a buyer-safe reason for every selected product."); return; }
    setIssuing(true); setMessage("Issuing buyer product shortlist…");
    try {
      const response = await fetch("/api/admin/recommendation", { method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ reference: record.reference, receivedAt: record.receivedAt, title, introduction, nextStep, issuedBy: record.owner, items: selectedCodes.map((code) => ({ code, reason: reasons[code] })) }) });
      const result = await response.json().catch(() => ({})); if (!response.ok || !result.ok) throw new Error(result.message || "Product shortlist could not be issued."); onSaved(result.record); setMessage(`Shortlist issued to the private buyer page${result.notificationSent ? " and emailed" : "; email was not sent"}.`);
    } catch (error) { setMessage(error instanceof Error ? error.message : "Product shortlist could not be issued."); }
    finally { setIssuing(false); }
  }
  return <details className="admin-product-recommendation"><summary>Curated product shortlist {record.recommendationSets?.length ? `· ${record.recommendationSets.length} version${record.recommendationSets.length === 1 ? "" : "s"}` : ""}</summary><div className="recommendation-editor"><div className="admin-follow-up-grid"><label className="admin-form-full">Buyer-facing title<input value={title} maxLength={160} onChange={(event) => setTitle(event.target.value)} /></label><label className="admin-form-full">Why these options<textarea rows={3} maxLength={1200} value={introduction} onChange={(event) => setIntroduction(event.target.value)} /></label><label className="admin-form-full">Suggested next step<textarea rows={2} maxLength={600} value={nextStep} onChange={(event) => setNextStep(event.target.value)} /></label></div><div className="recommendation-product-picker"><div><strong>Select 2–5 products</strong><span>{selectedCodes.length}/5 selected</span></div><div>{products.map((product) => <label key={product.code} className={selectedCodes.includes(product.code) ? "selected" : ""}><input type="checkbox" checked={selectedCodes.includes(product.code)} onChange={() => toggle(product.code)} disabled={!selectedCodes.includes(product.code) && selectedCodes.length >= 5} /><Image unoptimized src={`/catalog-thumbs/${product.slug}.webp`} alt="" width={64} height={64} /><span><strong>{product.code}</strong><small>{product.name}</small></span></label>)}</div></div>{selectedCodes.length ? <div className="recommendation-reasons">{selectedCodes.map((code) => { const product = products.find((item) => item.code === code)!; return <label key={code}><span><strong>{code}</strong> · {product.name}</span><textarea rows={2} maxLength={600} value={reasons[code] || ""} onChange={(event) => setReasons((current) => ({ ...current, [code]: event.target.value }))} placeholder="Buyer-safe reason based on verified product facts" /></label>; })}</div> : null}<button className="button button-small" type="button" disabled={issuing} onClick={issue}>{issuing ? "Issuing…" : "Issue shortlist to buyer"}</button><p aria-live="polite">{message}</p><small>Issue only verified product directions. This does not confirm price, availability, fit, materials, technical targets, sample terms or an order.</small>{currentRecommendation?.status === "issued" ? <section className="recommendation-nurture"><div><div><strong>Human-reviewed shortlist follow-up</strong><span>{followUps.length}/2 messages sent · {nextFollowUpStage ? `next: ${nextFollowUpStage.replaceAll("_", " ")} on ${followUpDue}` : "sequence complete"}</span></div>{nextFollowUpStage && <button type="button" onClick={loadFollowUp} disabled={!followUpReady}>Load next buyer-specific draft</button>}</div>{followUpBody && <><textarea rows={9} maxLength={2000} value={followUpBody} onChange={(event) => setFollowUpBody(event.target.value)} /><div><small>{followUpBody.length}/2000 · Review product facts and one clear next action.</small><button className="button button-small" type="button" disabled={sendingFollowUp} onClick={sendFollowUp}>{sendingFollowUp ? "Sending…" : "Save in thread & notify buyer"}</button></div></>}<small>No message is sent automatically. The first review is due two days after issue, the second four days after the first, and the sequence stops after two reviewed follow-ups or immediately after a buyer response.</small></section> : null}{record.recommendationSets?.length ? <div className="recommendation-history"><strong>Issued shortlist history</strong>{[...record.recommendationSets].reverse().map((item) => <article key={item.id}><div><strong>{item.title}</strong><span>{item.items.map((product) => product.code).join(" · ")} · {item.status.replaceAll("_", " ")}</span></div><small>{new Date(item.issuedAt).toLocaleString()} · {item.notificationSent ? "buyer emailed" : "email not sent"} · {item.followUps?.length || 0}/2 follow-ups</small>{item.buyerDecision && <p><b>Buyer response:</b> {item.buyerDecision.replaceAll("_", " ")}{item.selectedCodes?.length ? ` · ${item.selectedCodes.join(", ")}` : ""}{item.buyerNote ? ` · ${item.buyerNote}` : ""}</p>}{item.followUps?.length ? <ol>{item.followUps.map((followUp) => <li key={followUp.id}>{new Date(followUp.sentAt).toLocaleString()} · {followUp.stage.replaceAll("_", " ")} · {followUp.notificationSent ? "email sent" : "email not sent"}</li>)}</ol> : null}</article>)}</div> : null}</div></details>;
}

function FileLifecycleControl({ record, token, file, kind, onSaved }: { record: Inquiry; token: string; file: Attachment | OrderDocument; kind: "buyer_attachment" | "order_document"; onSaved: (record: Inquiry) => void }) {
  const [reason, setReason] = useState(""); const [message, setMessage] = useState(""); const [saving, setSaving] = useState(false); const action = file.revokedAt ? "restore" : "revoke";
  async function submit() {
    if (reason.trim().length < 3) { setMessage("Record a specific reason first."); return; }
    if (action === "revoke" && !window.confirm(`Withdraw access to ${file.name}? The stored evidence and audit history will remain.`)) return;
    setSaving(true); setMessage(`${action === "revoke" ? "Revoking" : "Restoring"} access…`);
    try { const response = await fetch("/api/admin/document-lifecycle", { method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ reference: record.reference, receivedAt: record.receivedAt, fileId: file.id, kind, action, reason, actor: record.owner || "Sales team" }) }); const result = await response.json().catch(() => ({})); if (!response.ok || !result.ok) throw new Error(result.message || "File lifecycle update failed."); onSaved(result.record); setReason(""); setMessage(`${action === "revoke" ? "Access revoked" : "Access restored"}; audit entry saved.`); }
    catch (error) { setMessage(error instanceof Error ? error.message : "File lifecycle update failed."); }
    finally { setSaving(false); }
  }
  return <div className={`file-lifecycle-control ${file.revokedAt ? "revoked" : ""}`}><input aria-label={`Reason to ${action} ${file.name}`} value={reason} onChange={(event) => setReason(event.target.value)} placeholder={`${action === "revoke" ? "Withdrawal" : "Restoration"} reason`} maxLength={600} /><button type="button" disabled={saving} onClick={submit}>{saving ? "Saving…" : action === "revoke" ? "Revoke access" : "Restore access"}</button><small>{file.revokedAt ? `Revoked ${new Date(file.revokedAt).toLocaleString()} · ${file.revocationReason}` : message}</small></div>;
}

function DocumentAuditHistory({ record }: { record: Inquiry }) {
  if (!record.documentAudit?.length) return null;
  return <details className="admin-document-audit"><summary>File lifecycle audit ({record.documentAudit.length})</summary><ol>{[...record.documentAudit].reverse().map((item) => <li key={item.id}><span>{new Date(item.changedAt).toLocaleString()}</span><strong>{item.action} · {item.kind.replaceAll("_", " ")} · {item.fileName}</strong><small>{item.actor} · {item.reason}</small></li>)}</ol><small>Revocation blocks website access but preserves the stored file and audit evidence. Permanent deletion requires a separate reviewed retention procedure.</small></details>;
}

function AttachmentList({ record, token, onSaved }: { record: Inquiry; token: string; onSaved: (record: Inquiry) => void }) {
  const [message, setMessage] = useState("");
  async function download(file: Attachment) {
    setMessage(`Preparing ${file.name}…`);
    try {
      const query = new URLSearchParams({ reference: record.reference, receivedAt: record.receivedAt, attachmentId: file.id });
      const response = await fetch(`/api/admin/inquiry-attachment?${query}`, { headers: { Authorization: `Bearer ${token}` }, cache: "no-store" });
      if (!response.ok) { const result = await response.json().catch(() => ({})); throw new Error(result.message || "Download failed."); }
      const url = URL.createObjectURL(await response.blob()); const link = document.createElement("a"); link.href = url; link.download = file.name; link.click(); URL.revokeObjectURL(url); setMessage(`${file.name} downloaded.`);
    } catch (error) { setMessage(error instanceof Error ? error.message : "Download failed."); }
  }
  if (!record.attachments?.length) return null;
  return <section className="admin-attachments"><small>BUYER FILES</small><div>{record.attachments.map((file) => <article key={file.id}><button type="button" onClick={() => download(file)} disabled={Boolean(file.revokedAt)}><strong>{file.name}</strong><span>{Math.ceil(file.size / 1024)} KB · {file.revokedAt ? "revoked" : "download"}</span></button><FileLifecycleControl record={record} token={token} file={file} kind="buyer_attachment" onSaved={onSaved} /></article>)}</div><p aria-live="polite">{message}</p></section>;
}

function InquiryMessageCenter({ record, token, onSaved }: { record: Inquiry; token: string; onSaved: (record: Inquiry) => void }) {
  const [body, setBody] = useState(""); const [status, setStatus] = useState(""); const [sending, setSending] = useState(false);
  const recommendedTemplate = recommendedBuyerMessageTemplate(record);
  function loadTemplate(id: BuyerMessageTemplateId) {
    if (body.trim()) { setStatus("Clear the current draft before loading another reply starter."); return; }
    setBody(buildBuyerMessageTemplate(record, id)); setStatus("Reply starter loaded. Review every detail before sending.");
  }
  async function send(event: React.FormEvent) {
    event.preventDefault(); if (body.trim().length < 2) { setStatus("Write a buyer-safe message before sending."); return; }
    setSending(true); setStatus("Saving message…");
    try {
      const response = await fetch("/api/admin/inquiry-message", { method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ reference: record.reference, receivedAt: record.receivedAt, message: body }) });
      const result = await response.json().catch(() => ({})); if (!response.ok || !result.ok) throw new Error(result.message || "Message could not be saved."); onSaved(result.record); setBody(""); setStatus(`Message saved${result.notificationSent ? " and emailed to the buyer" : "; buyer email was not sent"}.`);
    } catch (error) { setStatus(error instanceof Error ? error.message : "Message could not be saved."); }
    finally { setSending(false); }
  }
  return <details className="admin-message-center" open={Boolean(record.messages?.length)}><summary>Buyer message thread ({record.messages?.length || 0})</summary><div className="admin-message-thread">{record.messages?.length ? record.messages.map((message) => <article key={message.id} className={`admin-message admin-message-${message.sender}`}><div><strong>{message.sender === "buyer" ? "Buyer" : "Beiqiang"}</strong><time>{new Date(message.sentAt).toLocaleString()}</time>{message.sender === "sales" && <small>{message.notificationSent ? "Email sent" : "Email not sent"}</small>}</div><p>{message.body}</p></article>) : <p>No website messages yet.</p>}</div><section className="admin-reply-starters"><div><strong>Buyer-safe reply starters</strong><span>Recommended from current stage: {BUYER_MESSAGE_TEMPLATES.find((template) => template.id === recommendedTemplate)?.label}</span></div><div>{BUYER_MESSAGE_TEMPLATES.map((template) => <button key={template.id} className={template.id === recommendedTemplate ? "recommended" : ""} type="button" onClick={() => loadTemplate(template.id)} title={template.purpose}>{template.label}{template.id === recommendedTemplate ? " · recommended" : ""}</button>)}</div><small>Loading a starter does not send it. Verify buyer identity, product facts, quotation version and next action before using Save &amp; notify buyer.</small></section><form onSubmit={send}><label>Reply to buyer<textarea required minLength={2} maxLength={2000} rows={9} value={body} onChange={(event) => setBody(event.target.value)} placeholder="Buyer-safe reply. Do not include internal pricing, passwords or unconfirmed technical claims." /></label><div><small>{body.length}/2000</small><button className="button button-small" type="submit" disabled={sending}>{sending ? "Sending…" : "Save & notify buyer"}</button></div><p aria-live="polite">{status}</p></form></details>;
}

function PipelineHistory({ record }: { record: Inquiry }) {
  if (!record.pipelineHistory?.length) return null;
  return <details className="admin-pipeline-history"><summary>Stage history ({record.pipelineHistory.length})</summary><ol>{[...record.pipelineHistory].reverse().map((event, index) => <li key={`${event.changedAt}-${event.to}-${index}`}><span>{new Date(event.changedAt).toLocaleString()}</span><strong>{event.from ? `${event.from.replaceAll("_", " ")} → ` : ""}{event.to.replaceAll("_", " ")}</strong><small>{event.actor || "System"}{event.reason ? ` · ${event.reason.replaceAll("_", " ")}` : ""}</small></li>)}</ol></details>;
}

function AdminOrderDocuments({ record, token, onSaved }: { record: Inquiry; token: string; onSaved: (record: Inquiry) => void }) {
  const [file, setFile] = useState<File | null>(null); const [category, setCategory] = useState("sample_reference"); const [title, setTitle] = useState(""); const [note, setNote] = useState(""); const [status, setStatus] = useState(""); const [uploading, setUploading] = useState(false);
  function contentType(value: File) { if (value.type) return value.type; const extension = value.name.split(".").pop()?.toLowerCase(); return ({ pdf: "application/pdf", jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png", webp: "image/webp" } as Record<string, string>)[extension || ""] || ""; }
  async function upload(event: React.FormEvent) {
    event.preventDefault(); if (!file || !title.trim()) { setStatus("Choose a file and add a buyer-facing title."); return; } setUploading(true); setStatus("Preparing secure upload…");
    try { const common = { reference: record.reference, receivedAt: record.receivedAt, name: file.name, contentType: contentType(file), size: file.size, category, title, note }; const permissionResponse = await fetch("/api/admin/order-documents", { method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify(common) }); const permission = await permissionResponse.json().catch(() => ({})); if (!permissionResponse.ok || !permission.ok) throw new Error(permission.message || "Document upload could not start."); const putResponse = await fetch(permission.uploadUrl, { method: "PUT", headers: { "Content-Type": permission.contentType }, body: file }); if (!putResponse.ok) throw new Error("Document transfer failed."); const finalizeResponse = await fetch("/api/admin/order-documents", { method: "PATCH", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ ...common, uploadId: permission.uploadId, key: permission.key }) }); const result = await finalizeResponse.json().catch(() => ({})); if (!finalizeResponse.ok || !result.ok) throw new Error(result.message || "Document could not be attached."); onSaved({ ...record, orderDocuments: [...(record.orderDocuments || []), result.document], updatedAt: result.document.uploadedAt }); setFile(null); setTitle(""); setNote(""); setStatus(`Document saved${result.notificationSent ? " and buyer emailed" : "; buyer email was not sent"}.`); }
    catch (error) { setStatus(error instanceof Error ? error.message : "Document could not be uploaded."); }
    finally { setUploading(false); }
  }
  return <details className="admin-order-documents"><summary>Buyer document center ({record.orderDocuments?.length || 0})</summary><div className="admin-order-document-list">{record.orderDocuments?.length ? record.orderDocuments.map((document) => <article key={document.id} className={document.revokedAt ? "revoked" : ""}><div><small>{document.category.replaceAll("_", " ")}</small><strong>{document.title}</strong><span>{document.name} · {Math.ceil(document.size / 1024)} KB</span></div><span>{document.revokedAt ? "Access revoked" : document.notificationSent ? "Buyer emailed" : "Email not sent"}</span><FileLifecycleControl record={record} token={token} file={document} kind="order_document" onSaved={onSaved} /></article>) : <p>No buyer-facing documents yet.</p>}</div><form onSubmit={upload}><div className="admin-follow-up-grid"><label>Document category<select value={category} onChange={(event) => setCategory(event.target.value)}><option value="sample_reference">Sample reference</option><option value="approved_sample">Approved sample evidence</option><option value="specification">Specification</option><option value="quotation_support">Quotation support</option><option value="quality_inspection">Quality inspection</option><option value="packing">Packing</option><option value="shipping">Shipping</option><option value="order_document">Order document</option><option value="other">Other</option></select></label><label>Buyer-facing title<input required maxLength={160} value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Example: BQ009 approved color reference" /></label><label>PDF or image<input required type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" onChange={(event) => setFile(event.target.files?.[0] || null)} /></label><label className="admin-form-full">Buyer-safe note<textarea rows={2} maxLength={600} value={note} onChange={(event) => setNote(event.target.value)} placeholder="State what this document proves and any limits. Do not overstate unverified tests or specifications." /></label><button className="button button-small" type="submit" disabled={uploading}>{uploading ? "Uploading…" : "Upload & notify buyer"}</button><span aria-live="polite">{status}</span></div></form><small className="admin-document-boundary">Upload only reviewed buyer-facing evidence. A reference image is not an approved sample; a component result is not a finished-shoe test; a quotation is not an order.</small></details>;
}

function QuotationEditor({ record, token, onSaved }: { record: Inquiry; token: string; onSaved: (record: Inquiry) => void }) {
  const nextVersion = String((record.quotations?.length || 0) + 1);
  const sourceLines = record.items?.length ? record.items : record.styleCode.split(",").map((code) => ({ code: code.trim(), quantity: record.bulkQuantity || record.quantity }));
  const [version, setVersion] = useState(nextVersion); const [currency, setCurrency] = useState("USD"); const [tradeTerm, setTradeTerm] = useState("FOB");
  const [validUntil, setValidUntil] = useState(""); const [leadTime, setLeadTime] = useState(""); const [paymentTerms, setPaymentTerms] = useState("");
  const [packing, setPacking] = useState(""); const [sampleTerms, setSampleTerms] = useState(""); const [notes, setNotes] = useState(""); const [message, setMessage] = useState("");
  const [lines, setLines] = useState<QuotationLine[]>(sourceLines.map((item) => ({ code: item.code, description: `${item.code}${"colors" in item && item.colors ? ` · ${item.colors}` : ""}${"sizes" in item && item.sizes ? ` · ${item.sizes}` : ""}`, quantity: item.quantity || "", unitPrice: "" })));
  const total = lines.reduce((sum, line) => { const quantity = Number(String(line.quantity).replace(/[^\d.]/g, "")); const unitPrice = Number(line.unitPrice); return sum + (Number.isFinite(quantity) && Number.isFinite(unitPrice) ? quantity * unitPrice : 0); }, 0);
  function updateLine(index: number, field: keyof QuotationLine, value: string) { setLines((current) => current.map((line, lineIndex) => lineIndex === index ? { ...line, [field]: value } : line)); }
  function prepareRevision(quote: Quotation) { setVersion(nextVersion); setCurrency(quote.currency); setTradeTerm(quote.tradeTerm); setValidUntil(""); setLeadTime(quote.leadTime); setPaymentTerms(quote.paymentTerms); setPacking(quote.packing); setSampleTerms(quote.sampleTerms); setLines(quote.lines.map((line) => ({ ...line }))); setNotes(quote.notes); const brief = quote.revisionBrief; const targets = brief ? [`areas ${brief.reasons.map((item) => item.replaceAll("_", " ")).join(", ")}`, brief.affectedCodes.length ? `styles ${brief.affectedCodes.join(", ")}` : "", brief.targetQuantity ? `quantity ${brief.targetQuantity}` : "", brief.targetUnitPrice ? `unit-price ${brief.targetUnitPrice}` : "", brief.targetTradeTerm ? `trade term ${brief.targetTradeTerm}` : "", brief.requestedDelivery ? `delivery ${brief.requestedDelivery}` : "", brief.requestedPayment ? `payment ${brief.requestedPayment}` : "", brief.requestedPacking ? `packing ${brief.requestedPacking}` : "", brief.requestedSample ? `sample ${brief.requestedSample}` : ""].filter(Boolean).join(" · ") : ""; setMessage(`${quote.quoteNumber} copied into version ${nextVersion}. Buyer targets: ${targets || "review the saved response"}. Verify feasibility and edit every changed term before saving; targets are not copied into buyer-facing notes.`); }
  function quotePayload() { return { version, currency, tradeTerm, validUntil, leadTime, paymentTerms, packing, sampleTerms, notes, lines }; }
  async function save() {
    if (!lines.length || lines.some((line) => !line.code || !line.quantity || !line.unitPrice)) { setMessage("Complete quantity and unit price for every quote line."); return; }
    setMessage("Saving quotation version…");
    try {
      const response = await fetch("/api/admin/inquiries", { method: "PATCH", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ reference: record.reference, receivedAt: record.receivedAt, status: record.status, owner: record.owner, nextAction: record.nextAction, nextActionDue: record.nextActionDue, internalNote: record.internalNote, buyerUpdate: record.buyerUpdate, lastContactedAt: record.lastContactedAt, quotation: quotePayload() }) });
      const result = await response.json().catch(() => ({})); if (!response.ok || !result.ok) throw new Error(result.message || "Quotation could not be saved.");
      onSaved(result.record); setVersion(String((result.record.quotations?.length || 0) + 1)); setMessage(`${result.record.quotations.at(-1).quoteNumber} saved. Use Print / PDF to issue it after review.`);
    } catch (error) { setMessage(error instanceof Error ? error.message : "Quotation could not be saved."); }
  }
  async function issue(quote: Quotation) {
    setMessage(`Issuing ${quote.quoteNumber}…`);
    try {
      const response = await fetch("/api/admin/quotation", { method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ reference: record.reference, receivedAt: record.receivedAt, quoteNumber: quote.quoteNumber }) });
      const result = await response.json().catch(() => ({})); if (!response.ok || !result.ok) throw new Error(result.message || "Quotation could not be issued."); onSaved(result.record); setMessage(`${quote.quoteNumber} issued to the buyer status page${result.quoteEmailSent ? " and emailed" : "; email was not sent"}.`);
    } catch (error) { setMessage(error instanceof Error ? error.message : "Quotation could not be issued."); }
  }
  function printQuotation(quote: Quotation | ReturnType<typeof quotePayload>) {
    const quoteNumber = "quoteNumber" in quote ? quote.quoteNumber : `${record.reference}-Q${quote.version}`;
    const printable = window.open("", "_blank"); if (!printable) { setMessage("Allow pop-ups to open the print quotation."); return; } printable.opener = null;
    const quoteTotal = quote.lines.reduce((sum, line) => sum + (Number(String(line.quantity).replace(/[^\d.]/g, "")) || 0) * (Number(line.unitPrice) || 0), 0);
    const quoteDate = "issuedAt" in quote && quote.issuedAt ? quote.issuedAt.slice(0, 10) : "createdAt" in quote && quote.createdAt ? quote.createdAt.slice(0, 10) : new Date().toISOString().slice(0, 10);
    printable.document.write(`<!doctype html><html><head><title>${escapeHtml(quoteNumber)}</title><style>body{font:14px Arial;color:#17221d;margin:36px}header{display:flex;justify-content:space-between;border-bottom:3px solid #d69f36;padding-bottom:18px}h1{margin:0}small{color:#667}table{width:100%;border-collapse:collapse;margin:28px 0}th,td{border:1px solid #ccd5cf;padding:10px;text-align:left}th{background:#edf2ee}.terms{display:grid;grid-template-columns:1fr 1fr;gap:12px}.notice{margin-top:28px;padding:14px;background:#fff5dc}.total{text-align:right;font-size:18px}@media print{button{display:none}}</style></head><body><header><div><h1>BEIQIANG FOOTWEAR</h1><p>Quanzhou Beiqiang Footwear &amp; Apparel Co., Ltd.<br>Quanzhou, Fujian, China<br>421345308@qq.com · +86 189 5980 5256</p></div><div><strong>QUOTATION</strong><p>${escapeHtml(quoteNumber)}<br>${escapeHtml(quoteDate)}</p></div></header><h2>Buyer: ${escapeHtml(record.company)}</h2><p>Contact: ${escapeHtml(record.name)} · Market: ${escapeHtml(record.market)}<br>Inquiry: ${escapeHtml(record.reference)}</p><table><thead><tr><th>Style / description</th><th>Quantity</th><th>Unit price (${escapeHtml(quote.currency)})</th><th>Amount</th></tr></thead><tbody>${quote.lines.map((line) => `<tr><td><strong>${escapeHtml(line.code)}</strong><br>${escapeHtml(line.description)}</td><td>${escapeHtml(line.quantity)}</td><td>${escapeHtml(line.unitPrice)}</td><td>${((Number(String(line.quantity).replace(/[^\d.]/g, "")) || 0) * (Number(line.unitPrice) || 0)).toFixed(2)}</td></tr>`).join("")}</tbody></table><p class="total"><strong>Indicative total: ${escapeHtml(quote.currency)} ${quoteTotal.toFixed(2)}</strong></p><div class="terms"><p><strong>Trade term</strong><br>${escapeHtml(quote.tradeTerm)}</p><p><strong>Valid until</strong><br>${escapeHtml(quote.validUntil || "To be confirmed")}</p><p><strong>Lead time</strong><br>${escapeHtml(quote.leadTime || "Subject to final confirmation")}</p><p><strong>Payment terms</strong><br>${escapeHtml(quote.paymentTerms || "To be confirmed")}</p><p><strong>Packing</strong><br>${escapeHtml(quote.packing || "To be confirmed")}</p><p><strong>Sample terms</strong><br>${escapeHtml(quote.sampleTerms || "To be confirmed")}</p></div><p><strong>Notes</strong><br>${escapeHtml(quote.notes || "None")}</p><p class="notice"><strong>Commercial boundary:</strong> This quotation is subject to final written confirmation of specifications, approved sample, size ratio, packing, payment and shipping details. It is not a production order or test-result guarantee.</p><button onclick="window.print()">Print / Save PDF</button></body></html>`); printable.document.close();
  }
  return <details className="admin-quotation"><summary>Create quotation / PDF</summary><div className="quotation-editor"><div className="admin-follow-up-grid"><label>Version<input value={version} onChange={(event) => setVersion(event.target.value)} /></label><label>Currency<select value={currency} onChange={(event) => setCurrency(event.target.value)}><option>USD</option><option>EUR</option></select></label><label>Trade term<select value={tradeTerm} onChange={(event) => setTradeTerm(event.target.value)}><option>FOB</option><option>EXW</option><option>FCA</option><option>DDP</option></select></label><label>Valid until<input type="date" value={validUntil} onChange={(event) => setValidUntil(event.target.value)} /></label><label>Lead time<input value={leadTime} onChange={(event) => setLeadTime(event.target.value)} placeholder="Confirm after style / quantity review" /></label><label>Payment terms<input value={paymentTerms} onChange={(event) => setPaymentTerms(event.target.value)} placeholder="Enter confirmed terms" /></label><label>Packing<input value={packing} onChange={(event) => setPacking(event.target.value)} placeholder="Enter confirmed packing" /></label><label>Sample terms<input value={sampleTerms} onChange={(event) => setSampleTerms(event.target.value)} placeholder="Enter confirmed sample terms" /></label></div><div className="quotation-lines">{lines.map((line, index) => <div key={`${line.code}-${index}`}><input aria-label="Style code" value={line.code} onChange={(event) => updateLine(index, "code", event.target.value)} /><input aria-label="Description" value={line.description} onChange={(event) => updateLine(index, "description", event.target.value)} /><input aria-label="Quantity" value={line.quantity} onChange={(event) => updateLine(index, "quantity", event.target.value)} placeholder="Pairs" /><input aria-label="Unit price" inputMode="decimal" value={line.unitPrice} onChange={(event) => updateLine(index, "unitPrice", event.target.value)} placeholder="Unit price" /></div>)}</div><label>Quotation notes<textarea rows={3} value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Confirmed inclusions, exclusions or buyer-specific notes" /></label><p className="quotation-total">Calculated reference total: {currency} {total.toFixed(2)}</p><div className="quotation-actions"><button className="button button-small" type="button" onClick={save}>Save immutable version</button><button className="button button-small button-secondary" type="button" onClick={() => printQuotation(quotePayload())}>Preview draft</button></div><p aria-live="polite">{message}</p>{record.quotations?.length ? <div className="quotation-history"><strong>Saved versions</strong>{record.quotations.map((quote) => <div key={quote.quoteNumber}><button type="button" onClick={() => printQuotation(quote)}>{quote.quoteNumber} · {new Date(quote.createdAt).toLocaleString()} · Print / PDF</button><span>{quote.status || "draft"}{quote.quoteEmailSent ? " · emailed" : ""}{quote.revisionBrief ? ` · ${quote.revisionBrief.reasons.map((item) => item.replaceAll("_", " ")).join(", ")}` : ""}</span>{quote.status === "buyer_revision_requested" ? <button type="button" className="quote-revision-button" onClick={() => prepareRevision(quote)}>Use as revision draft</button> : !["buyer_accepted", "buyer_declined", "buyer_revision_requested"].includes(quote.status || "draft") ? <button type="button" className="quote-issue-button" onClick={() => issue(quote)}>Issue to buyer</button> : null}</div>)}</div> : null}</div></details>;
}

function SampleProgramEditor({ record, token, onSaved }: { record: Inquiry; token: string; onSaved: (record: Inquiry) => void }) {
  const sample = record.sampleProgram;
  const [sampleStatus, setSampleStatus] = useState(sample?.status || "brief_requested"); const [styleCodes, setStyleCodes] = useState(sample?.styleCodes || record.styleCode || ""); const [quantity, setQuantity] = useState(sample?.quantity || record.sampleQuantity || "");
  const [sampleReference, setSampleReference] = useState(sample?.sampleReference || ""); const [sizes, setSizes] = useState(sample?.sizes || ""); const [colors, setColors] = useState(sample?.colors || ""); const [purpose, setPurpose] = useState(sample?.purpose || ""); const [reviewScope, setReviewScope] = useState(sample?.reviewScope || ""); const [deliverables, setDeliverables] = useState(sample?.deliverables || ""); const [acceptanceCriteria, setAcceptanceCriteria] = useState(sample?.acceptanceCriteria || ""); const [exclusions, setExclusions] = useState(sample?.exclusions || "");
  const [currency, setCurrency] = useState(sample?.currency || "USD"); const [sampleCharge, setSampleCharge] = useState(sample?.sampleCharge || ""); const [chargeStatus, setChargeStatus] = useState(sample?.chargeStatus || "planned"); const [paidAt, setPaidAt] = useState(sample?.paidAt || "");
  const [courier, setCourier] = useState(sample?.courier || ""); const [trackingNumber, setTrackingNumber] = useState(sample?.trackingNumber || ""); const [shippedAt, setShippedAt] = useState(sample?.shippedAt || ""); const [expectedDelivery, setExpectedDelivery] = useState(sample?.expectedDelivery || ""); const [note, setNote] = useState(sample?.note || ""); const [message, setMessage] = useState("");
  async function save() {
    setMessage("Saving sample project…");
    try {
      const response = await fetch("/api/admin/inquiries", { method: "PATCH", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ reference: record.reference, receivedAt: record.receivedAt, status: record.status, owner: record.owner, nextAction: record.nextAction, nextActionDue: record.nextActionDue, internalNote: record.internalNote, buyerUpdate: record.buyerUpdate, lastContactedAt: record.lastContactedAt, sampleProgram: { status: sampleStatus, sampleReference, styleCodes, quantity, sizes, colors, purpose, reviewScope, deliverables, acceptanceCriteria, exclusions, currency, sampleCharge, chargeStatus, paidAt, courier, trackingNumber, shippedAt, expectedDelivery, note } }) });
      const result = await response.json().catch(() => ({})); if (!response.ok || !result.ok) throw new Error(result.message || "Sample project could not be saved."); onSaved(result.record); setMessage("Sample project saved. Use the buyer message thread to notify the buyer after reviewing the public fields.");
    } catch (error) { setMessage(error instanceof Error ? error.message : "Sample project could not be saved."); }
  }
  return <details className="admin-sample-program" open={sample?.status === "buyer_review"}><summary>Sample validation project {sample ? `· ${sample.status.replaceAll("_", " ")}` : ""}</summary><div className="admin-follow-up-grid"><label>Sample stage<select value={sampleStatus} onChange={(event) => setSampleStatus(event.target.value)}><option value="brief_requested">Brief requested</option><option value="terms_confirmed">Terms confirmed</option><option value="awaiting_sample_payment">Awaiting sample payment</option><option value="preparing">Preparing</option><option value="shipped">Shipped</option><option value="delivered">Delivered</option><option value="buyer_review">Awaiting buyer review</option><option value="buyer_approved" disabled>Buyer approved</option><option value="revision_requested" disabled>Buyer requested revision</option><option value="closed">Closed</option></select></label><label>Physical sample reference<input value={sampleReference} onChange={(event) => setSampleReference(event.target.value)} placeholder="Unique label on this physical sample" /></label><label>Style code(s)<input value={styleCodes} onChange={(event) => setStyleCodes(event.target.value)} placeholder="Exact product style codes" /></label><label>Sample quantity<input value={quantity} onChange={(event) => setQuantity(event.target.value)} placeholder="Pairs and allocation" /></label><label>Sizes<input value={sizes} onChange={(event) => setSizes(event.target.value)} placeholder="Exact sizes" /></label><label>Colors<input value={colors} onChange={(event) => setColors(event.target.value)} placeholder="Exact colors" /></label><label>Sample purpose<input value={purpose} onChange={(event) => setPurpose(event.target.value)} placeholder="Fit / color / branding / construction review" /></label><label className="admin-form-full">Review scope<textarea rows={3} value={reviewScope} onChange={(event) => setReviewScope(event.target.value)} placeholder="Write exactly what this review is intended to validate." /></label><label className="admin-form-full">Buyer review deliverables<textarea rows={3} value={deliverables} onChange={(event) => setDeliverables(event.target.value)} placeholder="Physical pair, photos, measurement sheet or other items actually supplied for this round." /></label><label className="admin-form-full">Acceptance criteria<textarea rows={3} value={acceptanceCriteria} onChange={(event) => setAcceptanceCriteria(event.target.value)} placeholder="Observable criteria the buyer should use for this specific sample review." /></label><label className="admin-form-full">Explicit exclusions<textarea rows={3} value={exclusions} onChange={(event) => setExclusions(event.target.value)} placeholder="Bulk material consistency, lab tests, final packing, size ratio or other items not validated by this round." /></label><label>Currency<select value={currency} onChange={(event) => setCurrency(event.target.value)}><option>USD</option><option>EUR</option></select></label><label>Sample charge<input inputMode="decimal" value={sampleCharge} onChange={(event) => setSampleCharge(event.target.value)} placeholder="Written amount only" /></label><label>Charge status<select value={chargeStatus} onChange={(event) => setChargeStatus(event.target.value)}><option value="planned">Planned</option><option value="due">Due</option><option value="paid">Paid</option><option value="waived">Waived</option></select></label>{chargeStatus === "paid" && <label>Actual paid date<input type="date" value={paidAt} onChange={(event) => setPaidAt(event.target.value)} /></label>}<label>Courier<input value={courier} onChange={(event) => setCourier(event.target.value)} placeholder="After actual shipment" /></label><label>Tracking reference<input value={trackingNumber} onChange={(event) => setTrackingNumber(event.target.value)} placeholder="After actual shipment" /></label><label>Actual shipment date<input type="date" value={shippedAt} onChange={(event) => setShippedAt(event.target.value)} /></label><label>Expected delivery<input type="date" value={expectedDelivery} onChange={(event) => setExpectedDelivery(event.target.value)} /></label><label className="admin-form-full">Buyer-safe sample note<textarea rows={3} value={note} onChange={(event) => setNote(event.target.value)} placeholder="Current action or limitation. Do not include internal cost or unverified test claims." /></label><button className="button button-small" type="button" onClick={save}>Save sample project</button><span aria-live="polite">{message}</span>{sample?.buyerDecision && <p className="admin-form-full sample-buyer-decision"><strong>Latest buyer response:</strong> {sample.buyerDecision.replaceAll("_", " ")} · {sample.buyerRespondedAt ? new Date(sample.buyerRespondedAt).toLocaleString() : "time unavailable"}<br />{sample.buyerNote || "No buyer note."}</p>}{sample?.reviewRounds?.length ? <details className="admin-form-full sample-review-rounds" open><summary>Immutable sample review rounds ({sample.reviewRounds.length})</summary>{[...sample.reviewRounds].reverse().map((round) => <article key={round.round}><div><strong>Round {round.round} · {round.sampleReference || "Legacy reference"}</strong><span>{round.status.replaceAll("_", " ")}</span></div><p>{round.styleCodes} · {round.purpose}</p><small>Scope: {round.reviewScope || "Legacy record"}</small><small>Deliverables: {round.deliverables || "Legacy record"}</small><small>Acceptance: {round.acceptanceCriteria || "Legacy record"}</small><small>Exclusions: {round.exclusions || "Legacy record"}</small>{round.decision && <p><b>Buyer:</b> {round.decision.replaceAll("_", " ")} · {round.buyerNote || "No note"}</p>}</article>)}</details> : null}{sample?.history?.length ? <details className="admin-form-full sample-history"><summary>Sample stage history ({sample.history.length})</summary><ol>{[...sample.history].reverse().map((item, index) => <li key={`${item.changedAt}-${index}`}><span>{new Date(item.changedAt).toLocaleString()}</span><strong>{item.from ? `${item.from.replaceAll("_", " ")} → ` : ""}{item.to.replaceAll("_", " ")}</strong><small>{item.actor}</small></li>)}</ol></details> : null}<small className="admin-form-full">Opening Buyer review freezes an immutable round. Approval applies only to that physical sample reference, deliverables, criteria and scope; it does not automatically confirm excluded bulk terms.</small></div></details>;
}

function BuyerOrderRequestSummary({ record }: { record: Inquiry }) {
  const requests = record.buyerOrderRequests || [];
  if (!requests.length) return null;
  return <details className="admin-buyer-order-request" open><summary>Buyer order-setup request · {requests.length}</summary><div>{[...requests].reverse().map((item) => <article key={item.id}><div><strong>{item.quoteNumber}</strong><span>{item.status.replaceAll("_", " ")} · {new Date(item.submittedAt).toLocaleString()}</span></div><dl><div><dt>Legal company</dt><dd>{item.legalCompanyName}</dd></div><div><dt>Purchasing contact</dt><dd>{item.purchasingContact}</dd></div><div><dt>Preferred channel</dt><dd>{item.preferredOrderChannel.replaceAll("_", " ")}</dd></div><div><dt>Buyer PO reference</dt><dd>{item.purchaseOrderReference || "Not supplied"}</dd></div><div><dt>Destination</dt><dd>{item.destination}</dd></div><div><dt>Requested window</dt><dd>{item.requestedWindow}</dd></div>{item.instructions && <div><dt>Instructions</dt><dd>{item.instructions}</dd></div>}</dl></article>)}</div><small>Treat this as a buyer request to prepare the formal order, not as an accepted production order. Verify the quotation and all eight order-readiness items before creating Trade Assurance or contract documents.</small></details>;
}

function OrderHandoffEditor({ record, token, onSaved }: { record: Inquiry; token: string; onSaved: (record: Inquiry) => void }) {
  const requestedChannel = record.buyerOrderRequests?.at(-1)?.preferredOrderChannel;
  const [method, setMethod] = useState<OrderHandoff["method"]>(record.orderHandoff?.method || (requestedChannel === "contract" ? "contract" : "alibaba_trade_assurance"));
  const [orderReference, setOrderReference] = useState(record.orderHandoff?.orderReference || ""); const [orderUrl, setOrderUrl] = useState(record.orderHandoff?.orderUrl || "");
  const [confirmedAt, setConfirmedAt] = useState(record.orderHandoff?.confirmedAt || ""); const [note, setNote] = useState(record.orderHandoff?.note || ""); const [message, setMessage] = useState("");
  const [fulfillmentStatus, setFulfillmentStatus] = useState(record.orderHandoff?.fulfillmentStatus || "order_documents"); const [carrier, setCarrier] = useState(record.orderHandoff?.carrier || ""); const [trackingNumber, setTrackingNumber] = useState(record.orderHandoff?.trackingNumber || "");
  const [paymentCurrency, setPaymentCurrency] = useState(record.orderHandoff?.paymentCurrency || "USD"); const [paymentMilestones, setPaymentMilestones] = useState<PaymentMilestone[]>(record.orderHandoff?.paymentMilestones || []);
  const emptyChecklist: OrderChecklist = { productSpecification: "", sampleDecision: "", quantitySizeRatio: "", colorsMaterials: "", packingLabeling: "", priceTradeTerm: "", paymentTerms: "", deliveryWindow: "" };
  const [orderChecklist, setOrderChecklist] = useState<OrderChecklist>(record.orderHandoff?.orderChecklist || emptyChecklist);
  function updateChecklist(field: keyof OrderChecklist, value: string) { setOrderChecklist((current) => ({ ...current, [field]: value })); }
  function addPaymentMilestone() { if (paymentMilestones.length >= 6) return; setPaymentMilestones((current) => [...current, { id: `PM-${current.length + 1}`, label: "", amount: "", dueDate: "", status: "planned", paidAt: "", reference: "", note: "" }]); }
  function updatePayment(index: number, field: keyof PaymentMilestone, value: string) { setPaymentMilestones((current) => current.map((item, itemIndex) => itemIndex === index ? { ...item, [field]: value } as PaymentMilestone : item)); }
  function removePayment(index: number) { setPaymentMilestones((current) => current.filter((item, itemIndex) => itemIndex !== index)); }
  const scheduledTotal = paymentMilestones.filter((item) => item.status !== "waived").reduce((sum, item) => sum + (Number(item.amount) || 0), 0); const paidTotal = paymentMilestones.filter((item) => item.status === "paid").reduce((sum, item) => sum + (Number(item.amount) || 0), 0); const checklistComplete = Object.values(orderChecklist).filter((value) => value.trim().length >= 2).length;
  async function save() {
    setMessage("Saving order handoff…");
    try {
      const response = await fetch("/api/admin/inquiries", { method: "PATCH", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ reference: record.reference, receivedAt: record.receivedAt, status: record.status, owner: record.owner, nextAction: record.nextAction, nextActionDue: record.nextActionDue, internalNote: record.internalNote, buyerUpdate: record.buyerUpdate, lastContactedAt: record.lastContactedAt, orderHandoff: { method, orderReference, orderUrl: method === "alibaba_trade_assurance" ? orderUrl : "", confirmedAt, note, fulfillmentStatus, carrier, trackingNumber, paymentCurrency, paymentMilestones, orderChecklist } }) });
      const result = await response.json().catch(() => ({})); if (!response.ok || !result.ok) throw new Error(result.message || "Order handoff could not be saved."); onSaved(result.record); setMessage("Order handoff saved. Confirm the pipeline stage only after both sides have accepted the order documents.");
    } catch (error) { setMessage(error instanceof Error ? error.message : "Order handoff could not be saved."); }
  }
  return <details className="admin-order-handoff"><summary>Trade Assurance / contract handoff · order readiness {checklistComplete}/8</summary><div className="admin-follow-up-grid"><label>Order method<select value={method} onChange={(event) => setMethod(event.target.value as OrderHandoff["method"])}><option value="alibaba_trade_assurance">Alibaba Trade Assurance</option><option value="contract">Bilateral contract</option></select></label><label>Order / contract reference<input value={orderReference} onChange={(event) => setOrderReference(event.target.value)} placeholder="Exact order or contract number" /></label><label>Confirmed date<input type="date" value={confirmedAt} onChange={(event) => setConfirmedAt(event.target.value)} /></label><label>Fulfillment stage<select value={fulfillmentStatus} onChange={(event) => setFulfillmentStatus(event.target.value)}><option value="order_documents">Order documents</option><option value="awaiting_payment">Awaiting payment</option><option value="payment_confirmed">Payment confirmed</option><option value="sampling">Sampling</option><option value="production">Production</option><option value="quality_check">Quality check</option><option value="ready_to_ship">Ready to ship</option><option value="shipped">Shipped</option><option value="completed">Completed</option><option value="on_hold">On hold</option></select></label><label>Carrier<input value={carrier} onChange={(event) => setCarrier(event.target.value)} placeholder="After shipment" /></label><label>Tracking / B/L reference<input value={trackingNumber} onChange={(event) => setTrackingNumber(event.target.value)} placeholder="After shipment" /></label>{method === "alibaba_trade_assurance" && <label className="admin-form-full">Alibaba Trade Assurance order URL<input type="url" value={orderUrl} onChange={(event) => setOrderUrl(event.target.value)} placeholder="https://...alibaba.com/..." /></label>}<label className="admin-form-full">Buyer-safe order note<textarea rows={3} value={note} onChange={(event) => setNote(event.target.value)} placeholder="What the buyer should do next. Do not include passwords, bank credentials or internal pricing." /></label><section className="admin-order-checklist admin-form-full"><div><strong>Written order-readiness checklist</strong><span>{checklistComplete}/8 complete. Every item must cite the agreed value or document reference before Order confirmed.</span></div><label>Product specification / document<input value={orderChecklist.productSpecification} onChange={(event) => updateChecklist("productSpecification", event.target.value)} placeholder="Approved specification version or document reference" /></label><label>Sample decision / reference<input value={orderChecklist.sampleDecision} onChange={(event) => updateChecklist("sampleDecision", event.target.value)} placeholder="Approved sample reference or written reason sample is not required" /></label><label>Quantity and size ratio<input value={orderChecklist.quantitySizeRatio} onChange={(event) => updateChecklist("quantitySizeRatio", event.target.value)} placeholder="Total pairs and final size breakdown" /></label><label>Colors and materials<input value={orderChecklist.colorsMaterials} onChange={(event) => updateChecklist("colorsMaterials", event.target.value)} placeholder="Final colors and material reference" /></label><label>Packing and labeling<input value={orderChecklist.packingLabeling} onChange={(event) => updateChecklist("packingLabeling", event.target.value)} placeholder="Box, carton, marks and labels" /></label><label>Price, trade term and named place<input value={orderChecklist.priceTradeTerm} onChange={(event) => updateChecklist("priceTradeTerm", event.target.value)} placeholder="Issued quote and exact named port/place" /></label><label>Payment terms<input value={orderChecklist.paymentTerms} onChange={(event) => updateChecklist("paymentTerms", event.target.value)} placeholder="Written payment schedule or order clause" /></label><label>Delivery / production window<input value={orderChecklist.deliveryWindow} onChange={(event) => updateChecklist("deliveryWindow", event.target.value)} placeholder="Confirmed production or delivery timing" /></label><small>Do not use vague placeholders. These values are buyer-visible and must match the issued quotation, Trade Assurance order or bilateral contract.</small></section><section className="admin-payment-schedule admin-form-full"><div><div><strong>Payment milestones</strong><span>Track agreed payment stages only. Never enter bank passwords, verification codes or full account credentials.</span></div><label>Currency<select value={paymentCurrency} onChange={(event) => setPaymentCurrency(event.target.value)}><option>USD</option><option>EUR</option></select></label></div>{paymentMilestones.map((item, index) => <article key={`${item.id}-${index}`}><input aria-label="Payment label" value={item.label} onChange={(event) => updatePayment(index, "label", event.target.value)} placeholder="Deposit / balance / freight" /><input aria-label="Payment amount" inputMode="decimal" value={item.amount} onChange={(event) => updatePayment(index, "amount", event.target.value)} placeholder="Amount" /><input aria-label="Payment due date" type="date" value={item.dueDate} onChange={(event) => updatePayment(index, "dueDate", event.target.value)} /><select aria-label="Payment status" value={item.status} onChange={(event) => updatePayment(index, "status", event.target.value)}><option value="planned">Planned</option><option value="due">Due</option><option value="paid">Paid</option><option value="waived">Waived</option></select>{item.status === "paid" && <input aria-label="Actual paid date" type="date" value={item.paidAt} onChange={(event) => updatePayment(index, "paidAt", event.target.value)} />}<input aria-label="Payment reference" value={item.reference} onChange={(event) => updatePayment(index, "reference", event.target.value)} placeholder="TA transaction / receipt reference" /><input aria-label="Payment note" value={item.note} onChange={(event) => updatePayment(index, "note", event.target.value)} placeholder="Buyer-safe note" /><button type="button" onClick={() => removePayment(index)}>Remove</button></article>)}<div className="payment-schedule-actions"><button type="button" onClick={addPaymentMilestone} disabled={paymentMilestones.length >= 6}>Add milestone</button><span>Scheduled {paymentCurrency} {scheduledTotal.toFixed(2)} · Paid {paymentCurrency} {paidTotal.toFixed(2)}</span></div></section><button className="button button-small" type="button" onClick={save}>Save order handoff</button><span aria-live="polite">{message}</span>{record.orderHandoff && <p className="admin-form-full order-handoff-saved"><strong>Saved:</strong> {record.orderHandoff.orderReference} · {record.orderHandoff.method.replaceAll("_", " ")} · {record.orderHandoff.fulfillmentStatus?.replaceAll("_", " ")}</p>}</div></details>;
}

function FollowUpEditor({ record, token, onSaved }: { record: Inquiry; token: string; onSaved: (record: Inquiry) => void }) {
  const [pipelineStatus, setPipelineStatus] = useState(record.status || "new");
  const [owner, setOwner] = useState(record.owner || "");
  const [nextAction, setNextAction] = useState(record.nextAction || "");
  const [nextActionDue, setNextActionDue] = useState(record.nextActionDue || "");
  const [internalNote, setInternalNote] = useState(record.internalNote || "");
  const [buyerUpdate, setBuyerUpdate] = useState(record.buyerUpdate || "");
  const [lastContactedAt, setLastContactedAt] = useState(record.lastContactedAt || "");
  const [lostReason, setLostReason] = useState(record.lostReason || "");
  const [message, setMessage] = useState("");

  async function save() {
    setMessage("Saving…");
    try {
      const response = await fetch("/api/admin/inquiries", { method: "PATCH", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ reference: record.reference, receivedAt: record.receivedAt, status: pipelineStatus, lostReason, owner, nextAction, nextActionDue, internalNote, buyerUpdate, lastContactedAt }) });
      const result = await response.json().catch(() => ({}));
      if (!response.ok || !result.ok) throw new Error(result.message || "Update failed.");
      onSaved(result.record); setMessage("Saved");
    } catch (error) { setMessage(error instanceof Error ? error.message : "Update failed."); }
  }

  return <details className="admin-follow-up"><summary>Update follow-up</summary><div className="admin-follow-up-grid"><label>Pipeline stage<select value={pipelineStatus} onChange={(event) => setPipelineStatus(event.target.value)}>{PIPELINE.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>{pipelineStatus === "lost" && <label>Primary lost reason<select required value={lostReason} onChange={(event) => setLostReason(event.target.value)}>{LOST_REASONS.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>}<label>Owner<input value={owner} onChange={(event) => setOwner(event.target.value)} placeholder="Salesperson" /></label><label>Last contacted<input type="date" value={lastContactedAt} onChange={(event) => setLastContactedAt(event.target.value)} /></label><label>Next action due<input type="date" value={nextActionDue} onChange={(event) => setNextActionDue(event.target.value)} /></label><label className="admin-form-full">Next action<input value={nextAction} onChange={(event) => setNextAction(event.target.value)} placeholder="One clear internal next action" /></label><label className="admin-form-full">Buyer-visible update<textarea value={buyerUpdate} onChange={(event) => setBuyerUpdate(event.target.value)} rows={3} placeholder="Safe progress message shown on the buyer status page. Do not include internal pricing or private notes." /></label><label className="admin-form-full">Internal note<textarea value={internalNote} onChange={(event) => setInternalNote(event.target.value)} rows={3} placeholder="Private quote, objection, sample or negotiation note" /></label><button className="button button-small" type="button" onClick={save}>Save follow-up</button><span aria-live="polite">{message}</span></div></details>;
}

export default function InquiryAdminPage() {
  const [token, setToken] = useState(""); const [records, setRecords] = useState<Inquiry[]>([]);
  const [status, setStatus] = useState("Enter the EdgeOne inquiry dashboard token to load records.");
  const [loading, setLoading] = useState(false); const [showTests, setShowTests] = useState(false); const [stageFilter, setStageFilter] = useState("all"); const [readinessFilter, setReadinessFilter] = useState("all"); const [sortMode, setSortMode] = useState("newest"); const [overdueOnly, setOverdueOnly] = useState(false); const [repeatOnly, setRepeatOnly] = useState(false);
  const [analytics, setAnalytics] = useState<CommercialAnalytics | null>(null); const [analyticsDays, setAnalyticsDays] = useState(30); const [analyticsLoading, setAnalyticsLoading] = useState(false);
  const [reminders, setReminders] = useState<ReminderSummary | null>(null); const [reminderLoading, setReminderLoading] = useState(false); const [reminderMessage, setReminderMessage] = useState("");
  const businessRecords = useMemo(() => records.filter((record) => !record.internalTest), [records]);
  const relationshipGroups = useMemo(() => buildRelationshipGroups(businessRecords), [businessRecords]);
  const relationshipByReference = useMemo(() => relationshipIndex(relationshipGroups), [relationshipGroups]);
  const readinessByReference = useMemo(() => new Map(records.map((record) => [record.reference, assessInquiryReadiness(record)])), [records]);
  const baseRecords = showTests ? records : businessRecords;
  const today = new Date().toISOString().slice(0, 10);
  const isOverdue = (record: Inquiry) => Boolean(record.nextActionDue && record.nextActionDue < today && !["lost", "spam", "order_confirmed"].includes(record.status));
  const stageRecords = stageFilter === "all" ? baseRecords : baseRecords.filter((record) => record.status === stageFilter);
  const dueRecords = overdueOnly ? stageRecords.filter(isOverdue) : stageRecords;
  const repeatRecords = repeatOnly ? dueRecords.filter((record) => relationshipByReference.has(record.reference)) : dueRecords;
  const readinessRecords = readinessFilter === "all" ? repeatRecords : repeatRecords.filter((record) => readinessByReference.get(record.reference)?.level === readinessFilter);
  const visibleRecords = [...readinessRecords].sort((left, right) => sortMode === "readiness"
    ? (readinessByReference.get(right.reference)?.score || 0) - (readinessByReference.get(left.reference)?.score || 0) || right.receivedAt.localeCompare(left.receivedAt)
    : right.receivedAt.localeCompare(left.receivedAt));
  const overdue = businessRecords.filter(isOverdue).length;
  const confirmed = businessRecords.filter((record) => record.status === "order_confirmed").length;
  const commerciallyReady = businessRecords.filter((record) => readinessByReference.get(record.reference)?.level === "ready").length;
  const recommendationsAwaitingBuyer = businessRecords.filter((record) => record.recommendationSets?.at(-1)?.status === "issued").length;
  const samplesAwaitingBuyer = businessRecords.filter((record) => record.sampleProgram?.status === "buyer_review").length;

  async function loadAnalytics(days = analyticsDays) {
    if (!token) return; setAnalyticsLoading(true);
    try { const response = await fetch(`/api/admin/analytics?days=${days}`, { headers: { Authorization: `Bearer ${token}` }, cache: "no-store" }); const result = await response.json().catch(() => ({})); if (!response.ok || !result.ok) throw new Error(result.message || "Commercial analytics could not be loaded."); setAnalytics(result.analytics); }
    catch (error) { setStatus(error instanceof Error ? error.message : "Commercial analytics could not be loaded."); }
    finally { setAnalyticsLoading(false); }
  }

  async function loadReminders(send = false) {
    if (!token) return; setReminderLoading(true); setReminderMessage(send ? "Sending today's internal digest…" : "Refreshing reminder preview…");
    try { const response = await fetch("/api/admin/reminders", { method: send ? "POST" : "GET", headers: { Authorization: `Bearer ${token}` }, cache: "no-store" }); const result = await response.json().catch(() => ({})); if (result.summary) setReminders(result.summary); if (!response.ok || !result.ok) throw new Error(result.message || "Sales reminders could not be loaded."); setReminderMessage(send ? `Digest sent at ${new Date(result.sentAt).toLocaleString()}.` : `${result.summary.counts.total} action reminders found.`); }
    catch (error) { setReminderMessage(error instanceof Error ? error.message : "Sales reminders could not be loaded."); }
    finally { setReminderLoading(false); }
  }

  async function loadRecords(event: React.FormEvent) {
    event.preventDefault(); setLoading(true); setStatus("Loading inquiry records…");
    try {
      const response = await fetch("/api/admin/inquiries", { headers: { Authorization: `Bearer ${token}` }, cache: "no-store" });
      const result = await response.json().catch(() => ({}));
      if (!response.ok || !result.ok) throw new Error(result.message || "Records could not be loaded.");
      setRecords(result.records || []); setStatus(`${(result.records || []).filter((record: Inquiry) => !record.internalTest).length} business inquiries loaded. Internal tests are excluded by default.`); await Promise.all([loadAnalytics(), loadReminders()]);
    } catch (error) { setRecords([]); setStatus(error instanceof Error ? error.message : "Records could not be loaded."); }
    finally { setLoading(false); }
  }

  function replaceRecord(updated: Inquiry) { setRecords((current) => current.map((record) => record.reference === updated.reference ? updated : record)); }
  function exportCsv() {
    const headers = ["Reference", "Readiness score", "Readiness level", "Qualification gaps", "Relationship group", "Related records", "Relationship match basis", "Received at", "Stage", "Lost reason", "Stage changes", "Owner", "Last contacted", "Next action due", "Next action", "Buyer update", "Email notified", "Project path", "Sourcing program", "Styles", "Name", "Company", "Buyer type", "Market", "Quantity", "Sample quantity", "Sample project status", "Physical sample reference", "Sample styles", "Sample review scope", "Sample deliverables", "Sample acceptance criteria", "Sample exclusions", "Sample review rounds", "Sample buyer decision", "Bulk quantity", "Trade-term preference", "Delivery destination", "Delivery timing", "Email", "WhatsApp", "Requirements", "Technical changes", "Buyer target/test", "NDA", "Recommendation versions", "Latest recommendation", "Recommended styles", "Recommendation status", "Buyer shortlist response", "Buyer shortlist styles", "Buyer shortlist note", "Buyer files", "Quotation versions", "Latest quotation", "Latest quote status", "Order setup requested", "Requested quote", "Requested channel", "Legal purchasing company", "Purchasing contact", "Buyer PO reference", "Requested destination", "Requested window", "Order method", "Order / contract reference", "Order confirmed date", "Fulfillment", "Payment currency", "Payment milestones", "Carrier", "Tracking / B/L", "Internal note", "UTM source", "UTM medium", "UTM campaign", "Page"];
    const rows = visibleRecords.map((record) => { const relationship = relationshipByReference.get(record.reference); const readiness = readinessByReference.get(record.reference); const buyerOrderRequest = record.buyerOrderRequests?.at(-1); const recommendation = record.recommendationSets?.at(-1); return [record.reference, readiness?.score, readiness?.level, readiness?.missing.join(" | "), relationship?.id, relationship?.records.length || 1, relationship?.matchBasis.join(" | "), record.receivedAt, record.status, record.lostReason, record.pipelineHistory?.length || 0, record.owner, record.lastContactedAt, record.nextActionDue, record.nextAction, record.buyerUpdate, record.notificationSent ? "Yes" : "No", record.projectPath, record.sourcingProgram, record.styleCode, record.name, record.company, record.buyerType, record.market, record.quantity, record.sampleQuantity, record.sampleProgram?.status, record.sampleProgram?.sampleReference, record.sampleProgram?.styleCodes, record.sampleProgram?.reviewScope, record.sampleProgram?.deliverables, record.sampleProgram?.acceptanceCriteria, record.sampleProgram?.exclusions, record.sampleProgram?.reviewRounds?.length || 0, record.sampleProgram?.buyerDecision, record.bulkQuantity, record.preferredTradeTerm, record.deliveryDestination, record.deliveryTiming, record.email, record.whatsapp, record.requirements, record.changesRequired, record.targetValues, record.ndaRequired, record.recommendationSets?.length || 0, recommendation?.id, recommendation?.items.map((item) => item.code).join(" | "), recommendation?.status, recommendation?.buyerDecision, recommendation?.selectedCodes?.join(" | "), recommendation?.buyerNote, record.attachments?.map((file) => file.name).join(" | "), record.quotations?.length || 0, record.quotations?.at(-1)?.quoteNumber, record.quotations?.at(-1)?.status, buyerOrderRequest?.submittedAt, buyerOrderRequest?.quoteNumber, buyerOrderRequest?.preferredOrderChannel, buyerOrderRequest?.legalCompanyName, buyerOrderRequest?.purchasingContact, buyerOrderRequest?.purchaseOrderReference, buyerOrderRequest?.destination, buyerOrderRequest?.requestedWindow, record.orderHandoff?.method, record.orderHandoff?.orderReference, record.orderHandoff?.confirmedAt, record.orderHandoff?.fulfillmentStatus, record.orderHandoff?.paymentCurrency, record.orderHandoff?.paymentMilestones?.map((item) => `${item.label}:${item.amount}:${item.status}`).join(" | "), record.orderHandoff?.carrier, record.orderHandoff?.trackingNumber, record.internalNote, record.attribution?.utmSource, record.attribution?.utmMedium, record.attribution?.utmCampaign, record.page]; });
    const csv = `\uFEFF${[headers, ...rows].map((row) => row.map(csvCell).join(",")).join("\r\n")}`; const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = `beiqiang-inquiries-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); URL.revokeObjectURL(url);
  }

  return <main className="admin-shell">
    <header className="admin-header"><div><p className="eyebrow">BEIQIANG INTERNAL</p><h1>Inquiry &amp; order pipeline</h1><p>Review sourcing requests, qualify buyers and move each opportunity through sample, quote, negotiation and confirmed order stages. Buyer-safe reply starters remain drafts until a salesperson reviews and sends them.</p></div><Link className="text-link" href="/">Return to website <span aria-hidden="true">↗</span></Link></header>
    <section className="admin-access-card"><form onSubmit={loadRecords}><label>Dashboard access token<input type="password" value={token} onChange={(event) => setToken(event.target.value)} autoComplete="current-password" required placeholder="Stored only in this page session" /></label><button className="button" type="submit" disabled={loading}>{loading ? "Loading…" : "Load inquiries"}</button></form><p className="admin-status" aria-live="polite">{status}</p></section>
    <CommercialDashboard data={analytics} days={analyticsDays} loading={analyticsLoading} onDaysChange={(days) => { setAnalyticsDays(days); void loadAnalytics(days); }} onRefresh={() => void loadAnalytics()} />
    <ReminderCenter summary={reminders} loading={reminderLoading} message={reminderMessage} onRefresh={() => void loadReminders()} onSend={() => void loadReminders(true)} />
    <RelationshipCenter groups={relationshipGroups} onShowRepeat={() => { setRepeatOnly(true); setShowTests(false); setOverdueOnly(false); setStageFilter("all"); }} />
    <section className="admin-metrics" aria-label="Inquiry summary"><article><small>BUSINESS INQUIRIES</small><strong>{businessRecords.length}</strong></article><article><small>COMMERCIAL-REVIEW READY</small><strong>{commerciallyReady}</strong></article><article><small>SHORTLISTS AWAITING BUYER</small><strong>{recommendationsAwaitingBuyer}</strong></article><article><small>SAMPLES AWAITING BUYER</small><strong>{samplesAwaitingBuyer}</strong></article><article><small>FOLLOW-UP OVERDUE</small><strong>{overdue}</strong></article><article><small>ACTIVE PIPELINE</small><strong>{businessRecords.filter((record) => !["lost", "spam", "order_confirmed"].includes(record.status)).length}</strong></article><article><small>ORDERS CONFIRMED</small><strong>{confirmed}</strong></article></section>
    <section className="admin-ledger"><div className="admin-toolbar"><div><label><input type="checkbox" checked={showTests} onChange={(event) => setShowTests(event.target.checked)} /> Show internal tests</label><label><input type="checkbox" checked={repeatOnly} onChange={(event) => setRepeatOnly(event.target.checked)} /> Repeat-account signals only</label><label><input type="checkbox" checked={overdueOnly} onChange={(event) => setOverdueOnly(event.target.checked)} /> Overdue follow-up only</label><label>Stage <select value={stageFilter} onChange={(event) => setStageFilter(event.target.value)}><option value="all">All</option>{PIPELINE.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><label>Brief readiness <select value={readinessFilter} onChange={(event) => setReadinessFilter(event.target.value)}><option value="all">All</option><option value="ready">Ready for review</option><option value="qualify">Qualification needed</option><option value="early">Early / incomplete</option></select></label><label>Sort <select value={sortMode} onChange={(event) => setSortMode(event.target.value)}><option value="newest">Newest first</option><option value="readiness">Readiness score</option></select></label></div><button type="button" className="button button-small" onClick={exportCsv} disabled={!visibleRecords.length}>Export pipeline CSV</button></div>
      <div className="admin-cards">{visibleRecords.map((record) => { const relationship = relationshipByReference.get(record.reference); const readiness = readinessByReference.get(record.reference)!; return <article className="admin-inquiry-card" id={record.reference} key={record.reference}>
        <div className="admin-card-top"><div><span className={`status-pill status-${record.status}`}>{record.status.replaceAll("_", " ")}</span><span className={`status-pill status-readiness-${readiness.level}`}>{readiness.score}/100 · {readiness.label}</span>{record.sampleProgram && <span className="status-pill status-sample">Sample · {record.sampleProgram.status.replaceAll("_", " ")}</span>}{record.lostReason && <span className="status-pill">{record.lostReason.replaceAll("_", " ")}</span>}{isOverdue(record) && <span className="status-pill status-overdue">Follow-up overdue</span>}{relationship && <span className="status-pill status-repeat">Repeat signal · {relationship.records.length}</span>}<h2>{record.company}</h2><p>{record.name} · {record.buyerType} · {record.market}</p></div><div><strong>{record.reference}</strong><small>{record.receivedAt ? new Date(record.receivedAt).toLocaleString() : "—"}</small>{record.nextActionDue && <small>Next action due {record.nextActionDue}</small>}</div></div>
        <section className={`admin-readiness admin-readiness-${readiness.level}`}><div><small>BUYING-BRIEF READINESS</small><strong>{readiness.score}/100 · {readiness.label}</strong><p>{readiness.summary}</p></div><div><small>NEXT QUALIFICATION QUESTIONS</small>{readiness.missing.length ? <ul>{readiness.missing.slice(0, 4).map((item) => <li key={item}>{item}</li>)}</ul> : <p>No structural gap detected. Verify product facts and commercial terms before issuing a quotation.</p>}</div></section>
        <div className="admin-card-grid"><div><small>STYLES / QUANTITY</small><strong>{record.styleCode}</strong><p>{record.bulkQuantity || record.quantity}</p><p><b>Trade / destination:</b> {record.preferredTradeTerm || "not sure"} · {record.deliveryDestination || "destination TBD"}{record.deliveryTiming ? ` · ${record.deliveryTiming}` : ""}</p>{record.items?.length ? <ul>{record.items.map((item) => <li key={item.code}>{item.code}: {item.quantity || "qty TBD"} · {item.colors || "colors TBD"} · {item.sizes || "sizes TBD"}</li>)}</ul> : null}</div><div><small>PROJECT / REQUIREMENTS</small><strong>{record.projectPath?.replaceAll("_", " ") || "standard inquiry"}</strong>{record.sourcingProgram && <p><b>Entry program:</b> {record.sourcingProgram.replaceAll("-", " ")}</p>}<p>{record.requirements || "No extra requirements"}</p>{record.changesRequired && <p><b>Changes:</b> {record.changesRequired}</p>}{record.targetValues && <p><b>Buyer targets:</b> {record.targetValues}</p>}</div><div><small>CONTACT / SOURCE</small><strong>{record.email || record.whatsapp || "—"}</strong><p>{record.whatsapp && record.email ? record.whatsapp : ""}</p><p>{record.attribution?.utmSource || "Direct"} · {record.attribution?.utmCampaign || record.page || "—"}</p><span className={record.notificationSent ? "status-pill status-ok" : "status-pill"}>{record.notificationSent ? "Email sent" : "Email not sent"}</span></div></div>
        <RelatedInquiryHistory current={record} group={relationship} />
        <ProductRecommendationEditor key={`recommendation-${record.reference}-${record.updatedAt}`} record={record} token={token} onSaved={replaceRecord} />
        <AttachmentList record={record} token={token} onSaved={replaceRecord} />
        <AdminOrderDocuments key={`documents-${record.reference}-${record.updatedAt}`} record={record} token={token} onSaved={replaceRecord} />
        <DocumentAuditHistory record={record} />
        <InquiryMessageCenter key={`messages-${record.reference}-${record.updatedAt}`} record={record} token={token} onSaved={replaceRecord} />
        <PipelineHistory record={record} />
        <FollowUpEditor key={`followup-${record.reference}-${record.updatedAt}`} record={record} token={token} onSaved={replaceRecord} />
        <SampleProgramEditor key={`sample-${record.reference}-${record.updatedAt}`} record={record} token={token} onSaved={replaceRecord} />
        <QuotationEditor key={`quote-${record.reference}-${record.updatedAt}`} record={record} token={token} onSaved={replaceRecord} />
        <BuyerOrderRequestSummary record={record} />
        <OrderHandoffEditor key={`order-${record.reference}-${record.updatedAt}`} record={record} token={token} onSaved={replaceRecord} />
      </article>; })}{!visibleRecords.length && <p className="admin-empty">No records to display.</p>}</div>
    </section>
  </main>;
}
